#pragma once
#include <juce_gui_basics/juce_gui_basics.h>
#include <BinaryData.h>   // generated by juce_add_binary_data() from /Resources

namespace msc::assets
{
// Look a resource up by its ORIGINAL file name (e.g. "banner_01_purple.jpg").
inline const char* find (const juce::String& originalName, int& size)
{
    for (int i = 0; i < BinaryData::namedResourceListSize; ++i)
    {
        const char* name = BinaryData::namedResourceList[i];
        if (const char* orig = BinaryData::getNamedResourceOriginalFilename (name))
            if (originalName == orig)
                return BinaryData::getNamedResource (name, size);
    }
    size = 0;
    return nullptr;
}

inline juce::Image image (const juce::String& originalName)
{
    int size = 0;
    if (const char* d = find (originalName, size))
        return juce::ImageCache::getFromMemory (d, size);
    return {};
}

inline juce::String text (const juce::String& originalName)
{
    int size = 0;
    if (const char* d = find (originalName, size))
        return juce::String::fromUTF8 (d, size);
    return {};
}

// Original file names that start with `prefix` and end with `suffix`, sorted alphabetically.
inline juce::StringArray list (const juce::String& prefix, const juce::String& suffix)
{
    juce::StringArray out;
    for (int i = 0; i < BinaryData::namedResourceListSize; ++i)
        if (const char* orig = BinaryData::getNamedResourceOriginalFilename (BinaryData::namedResourceList[i]))
        {
            const juce::String s (orig);
            if (s.startsWith (prefix) && s.endsWith (suffix)) out.add (s);
        }
    out.sort (false);
    return out;
}
} // namespace msc::assets
